export function mockProductPage(filter: ProductFilter = {}): PageResponse<Product> {
  let list = mockProducts;
  if (filter.keyword) list = list.filter((x) => x.name.toLowerCase().includes(filter.keyword!.toLowerCase()));
  if (filter.categoryId) list = list.filter((x) => x.categoryId === filter.categoryId);
  if (filter.minPrice != null) list = list.filter((x) => x.price >= filter.minPrice!);
  if (filter.maxPrice != null) list = list.filter((x) => x.price <= filter.maxPrice!);
  const size = filter.size ?? 20;
  const page = filter.page ?? 0;
  return {
    content: list.slice(page * size, page * size + size),
    page,
    size,
    totalElements: list.length,
    totalPages: Math.max(1, Math.ceil(list.length / size)),
    last: (page + 1) * size >= list.length,
  };
}

