/** Gọi API thật, lỗi (backend tắt) thì trả dữ liệu mẫu. */
export async function withMock<T>(call: Promise<T>, fallback: () => T): Promise<T> {
  try {
    return await call;
  } catch {
    return fallback();
  }
}

