export const mockServiceDetails: Record<string, { title: string; blocks: ArticleBlock[] }> = {"kham-tong-quat": {"title": "Dịch vụ khám sức khoẻ định kỳ cho thú cưng", "blocks": [["p", "Việc khám sức khỏe định kỳ cho thú cưng là một vấn đề rất cần thiết và cần phải được duy trì thường xuyên nếu như bạn muốn thú cưng của mình luôn khỏe mạnh, đáng yêu và dễ thương. Ngay bây giờ hãy cùng Thú yVet Clinic tìm hiểu thêm về dịch vụ này nhé!"], ["img", "/mock-images/dv/kham-tong-quat-1.jpg"], ["h3", "Khám sức khỏe định kỳ cho thú cưng là gì?"], ["p", "Khám sức khỏe định kỳ cho thú cưng chính là một dịch vụ rất phổ biến tại các phòng khám thú y, bệnh viện thú y hiện nay. Nhờ vào khám sức khỏe định kỳ mà bác sĩ thú y có thể phát hiện ra các dấu hiệu nguy hiểm xảy ra trên cơ thể của thú cưng và đưa ra các phác đồ điều trị phù hợp."], ["p", "Việc khám sức khỏe định kỳ cho thú cưng không chỉ giúp chúng ta phát hiện ra các bệnh lý mà thú cưng gặp phải mà còn giúp duy trì sức khỏe của thú cưng luôn ở trạng thái tốt và ổn định."], ["h3", "Vì sao nên thường xuyên khám sức khỏe định kỳ cho thú cưng?"], ["p", "Tuổi thọ trung bình của thú cưng khoảng từ 10 – 15 năm và nếu như chúng ta không có các phương pháp để chăm sóc sức khỏe cho chúng một cách khoa học thông qua các buổi thăm khám sức khỏe định kỳ thì tuổi thọ của chúng sẽ bị giảm sút nhanh chóng. Thậm chí có nhiều thú cưng do không phát hiện được ra bệnh mà tuổi thọ chỉ kéo dài được từ vài tháng cho tới vài năm."], ["p", "Dưới đây là một vài lý do mà Vet Clinic khuyên bạn nên kiểm tra sức khỏe định kỳ cho thú cưng:"], ["h4", "1. Phát hiện bệnh một cách nhanh chóng"], ["p", "Các dấu hiệu bệnh của thú cưng không phải lúc nào cũng có triệu chứng rõ ràng. Chính vì thế thông qua các cuộc khám sức khỏe định kỳ các bác sĩ sẽ kiểm tra thể chất bằng cách tiến hành lấy và phân tích máu, kiểm tra phân. Đặc biệt đối với những thú cưng lớn tuổi thì thể chất càng kém và việc kiểm tra càng trở nên quan trọng hơn."], ["p", "Qua những kết quả, thông số hiển thị trong đợt kiểm tra thì các bác sĩ thú y sẽ phát hiện sớm các bệnh nguy hiểm hoặc dễ dàng kiểm soát tình trạng mất cân bằng dinh dưỡng – một trong những nguyên nhân hàng đầu gây ra các bệnh về tim mạch, béo phì, tiểu đường, suy tuyến giáp… ở thú cưng."], ["h4", "2. Dễ dàng điều trị các căn bệnh mà thú cưng gặp phải"], ["p", "Các căn bệnh trên thú cưng sẽ trở nên trầm trọng nếu như chúng ta phát hiện bệnh quá trễ nhất là về mắt, răng, tai, suy tim, suy thận mãn, viêm gan…Đây là những bệnh chỉ được phát hiện nhờ vào quá trình xét nghiệm tổng quát, siêu âm, chụp X-quang,…Nhờ vào việc khám Khám sức khỏe định kỳ thì các bác sĩ sẽ dễ dàng điều trị dứt điểm mọi bệnh lý mà thú cưng gặp phải."], ["h4", "3. Phòng bệnh tốt nhất"], ["p", "Cũng giống như cơ thể của con người thì thú cưng nhà bạn sẽ được phòng ngừa và có khả năng chống lại bệnh tật tốt nhất khi được tiêm chủng vắc-xin. Chính vì thế thông qua các cuộc khám sức khỏe định kỳ, các bác sĩ thú y sẽ tư vấn giúp bạn những mũi vắc-xin mà thú cưng của bạn còn thiếu hoặc những mũi vắc-xin mới xuất hiện hiện nay."], ["p", "Nhờ vào việc tiêm chủng này mà thú cưng sẽ có khả năng chống chọi bệnh tật và phòng tránh được nhiều loại bệnh gây hại cho cơ thể."], ["h4", "4. Giúp bạn giải tỏa lo âu"], ["p", "Thông qua những cuộc khám sức khỏe định kỳ bạn sẽ có cơ hội được gặp đội ngũ bác sĩ thú y nhiều kinh nghiệm và từ đó có thể đưa ra những thắc mắc của mình về cách chăm sóc thú cưng thế nào cho hợp lý hoặc đưa ra những lo lắng về hành vi, tình trạng bất thường của thú cưng hiện nay."], ["p", "Chắc chắn với sự chuyên nghiệp của mình thì những lo âu của bạn sẽ được các bác sĩ tư vấn và giải thích cụ thể ngay tại buổi thăm khám."], ["h4", "5. Hạn chế tình trạng lây nhiễm bệnh từ thú cưng"], ["p", "Khi phát hiện được bệnh, thú cưng của bạn sẽ được điều trị kịp thời từ đó hạn chế được tình trạng lây nhiễm bệnh từ thú cưng sang thú cưng, từ thú cưng sang người. Từ đó có thể đảm bảo được sức khỏe cho cả người và vật nuôi được an toàn nhất."], ["p", "Tóm lại thông qua những lợi ích trên thì bạn đã biết được tầm quan trọng của việc khám sức khỏe định kỳ cho thú cưng chưa nào? Vậy nên lựa chọn bệnh viện thú y nào để thú cưng nhà bạn khám sức khỏe định kỳ đây? Nếu như bạn vẫn đang băn khoăn trong việc tìm kiếm một phòng khám thú y chất lượng thì hãy ghé qua Vet Clinic để cảm nhận sự khác biệt."], ["h3", "Vì sao nên khám sức khỏe định kỳ cho thú cưng tại Vet Clinic"], ["img", "/mock-images/dv/kham-tong-quat-2.jpg"], ["p", "Định kỳ hàng năm từ 1 – 2 lần bạn nên đưa thú cưng đi khám sức khỏe định kỳ. Việc thăm khám này sẽ giúp các bạn phát hiện sớm một số triệu chứng bệnh mà thú cưng gặp phải từ đó tiết kiệm được chi phí trong việc điều trị cũng như giúp thú cưng được khỏe mạnh hơn."], ["p", "Dưới đây là những lý do mà bạn nên lựa chọn Vet Clinic:"], ["li", "Vet Clinic chính là một địa chỉ cung cấp dịch vụ khám, chăm sóc sức khỏe cho thú cưng uy tín, chất lượng hàng đầu tại thành phố Hồ Chí Minh. Lựa chọnVet Clinic bạn sẽ được yên tâm tuyệt đối về hiệu quả của dịch vụ cũng như chuyên môn của đội ngũ y bác sĩ và cơ sở trang thiết bị y tế hiện đại."], ["li", "Không chỉ khám chữa bệnh, Vet Clinic còn hỗ trợ các chủ thú cưng cách chăm sóc thú cưng chính xác nhất, khoa học nhất, hiện đại nhất từ đó hạn chế tối đa sự phát triển của các loại bệnh gây ảnh hưởng tới sức khỏe của thú cưng."], ["li", "Sử dụng dịch vụ của khám sức khỏe định kỳ cho thú cưng củaVet Clinic bạn sẽ tiết kiệm chi phí, thời gian điều trị từ đó giúp cho thú cưng khỏe mạnh hơn, vui vẻ hơn và đáng yêu hơn."], ["h3", "Các công đoạn khám sức khỏe định kỳ cho thú cưng"], ["li", "Lựa chọn dịch vụ khám sức khỏe định kỳ tại Vet Clinic, thú cưng của bạn sẽ được:"], ["li", "Khám sức khỏe tổng quát như đo cân nặng, đo nhiệt độ, đo áp huyết, kiểm tra tai, mũi, họng, mắt…"], ["li", "Siêu âm kiểm tra ổ bụng, gan, tim, thận."], ["li", "Chụp X-quang kiểm tra xương khớp, tim phổi, hệ tiêu hóa, sỏi bàng quang, khối u ở trong cơ thể."], ["li", "Xét nghiệm máu phân tích các chỉ số và kiểm tra ký sinh trùng ở trong đường máu."], ["img", "/mock-images/dv/kham-tong-quat-3.jpg"], ["li", "Chăm sóc, vệ sinh thú cưng sạch sẽ."], ["p", "Sau khi có được kết quả của dịch vụ thì các bác sĩ sẽ tư vấn chủ nuôi về chế độ chăm sóc, nuôi dưỡng và huấn luyện thú cưng. Ngoài ra sẽ có thông tin hướng dẫn chế độ dinh dưỡng cần bổ sung để thú cưng luôn phát triển một cách khỏe mạnh."], ["p", "Có thể nói khám sức khỏe định kỳ cho thú cưng là một trong những cách tốt nhất giúp thú cưng của bạn khỏe mạnh và gia tăng tuổi thọ. Chính vì thế hãy ghé ngay Bệnh viện Thú y Thithi để sử dụng dịch vụ đi nào."], ["p", "Thú yVet Clinic chính là một trong những địa chỉ hàng đầu tại thành phố Hồ Chí Minh chuyên cung cấp các dịch vụ khám định kỳ thú cưng, tiêm phòng, tắm, chữa bệnh, chăm sóc thú cưng lễ tết…"]]}, "phau-thuat": {"title": "Dịch vụ tiểu phẫu, đại phẫu cho chó mèo", "blocks": [["p", "Khi chó mèo của bạn bị những chấn thương như rách da hở to, hay chấn thương kín thì bắt buộc cần phải được các bác sĩ có chuyên môn cao phẫu thuật. Vậy đâu là phòng khám cung cấp dịch vụ tiểu phẫu, đại phẫu tốt nhất Cần Thơ?"], ["img", "/mock-images/dv/phau-thuat-1.jpg"], ["h3", "Tiểu phẫu, đại phẫu cho chó mèo được tiến hành như thế nào?"], ["p", "Phẫu thuật được thực hiện sau những chẩn đoán, xét nghiệm, kiểm tra của bác sĩ thú ý đối với tình trạng của vật nuôi. Trường hợp buộc phải phẫu thuật để đảm bảo sức khỏe, tính mạng của vật nuôi, dịch vụ phẫu thuật chó mèo cho phép thực hiện nhanh chóng, hiệu quả nhất, giúp vật nuôi sống khỏe mạnh, ổn định."], ["p", "Phẫu thuật cho chó mèo nghĩa là đưa chó mèo lên bàn mổ. Các bác sĩ thú y sẽ phải dùng đến dao, kéo, kìm, kẹp, v.v.. để mổ ở bụng, chân, cổ, hay lưng, v.v.. của chó mèo. Tùy vào chó mèo bị bệnh gì sẽ được tiến hành mổ ở vị trí quy định. Sau khi tiến hành mổ và điều trị xong, các bác sĩ sẽ may vết mổ đó lại, băng bó và chăm sóc cho đến khi vết mổ lành hẳn."], ["img", "/mock-images/dv/phau-thuat-2.jpg"], ["p", "Phẫu thuật ngoại là một kỹ thuật không dễ dàng, bác sĩ cần phải suy xét và cân nhắc rất nhiều yếu tố, từ các biến chứng tiềm ẩn cho đến tiên lượng hồi phục. Tuy nhiên, vì y học thú y đã tiến bộ để bao gồm tất cả các cân nhắc hiện đại, nên nguy cơ thú cưng của bạn gặp bất kỳ biến chứng lớn nào từ hầu hết các cuộc phẫu thuật là rất thấp."], ["h3", "Địa chỉ cung cấp dịch vụ tiểu phẫu, đại phẫu cho chó mèo tốt nhất Cần Thơ"], ["img", "/mock-images/dv/phau-thuat-3.jpg"], ["p", "Vet Clinic là một trong những đơn vị đi đầu trong lĩnh vực chăm sóc thú cưng cũng như cung cấp các dịch vụ khám và điều trị cho chó mèo. Khi lựa chọnVet Clinic cho thú cưng của bạn sẽ được điều trị nhanh chóng, hưởng nhiều lợi ích và đảm bảo sức khỏe. Tính tới thời điểm hiện nay, Vet Clinic đã điều trị và cứu sống hàng triệu ca ở các loại thú cưng. Chính vì vậy, Vet Clinic đã và đang là địa chỉ đáng tin cậy của nhiều người chăm sóc thú cưng."], ["li", "Có mặt nhanh chóng, kịp thời: với đội ngũ đông đảo các y bác sĩ kinh nghiệm từ 10 năm được đào tạo bài bản trong và ngoài nước túc trực 24/24 nhận bệnh và có mặt kịp thời để đảm bảo sức khỏe và tính mạng cho thú cưng của bạn."], ["li", "Các trang thiết bị đầy đủ: các thiết bị y tế phục vụ cho điều trị tại chỗ và điều trị tại nhà đều được trang bị đầy đủ và hiện đại."], ["li", "Làm việc nhiệt tình, hiệu quả: trong suốt quá trình điều trị và sau điều trị chó mèo, thú cưng của bạn sẽ luôn được đảm bảo theo dõi thường xuyên sự phát triển của bệnh, sớm phát hiện và ứng phó kịp thời đối với những diễn biến nguy hiểm, cung cấp đầy đủ thông tin cần thiết về việc chăm sóc và phục hồi sức khỏe cho thú cưng."], ["li", "Chi phí hợp lý: việc điều trị chó mèo tạiVet Clinic bạn sẽ tiết kiệm được chi phí một cách tối đa được hưởng nhiêu ưu đãi riêng biệt khác."], ["img", "/mock-images/dv/phau-thuat-4.jpg"], ["h3", "Các dịch vụ tiểu phẫu ,đại phẫu tại Vet Clinic"], ["p", "Bệnh viện Thú yVet Clinic được thành lập từ 2012 với đội ngũ bác sĩ, phẫu thuật viên, gây mê hồi sức cùng điều dưỡng giàu kinh nghiệm chuyên môn, tận tâm và hệ thống phòng mổ hiện đại, bệnh viện đáp ứng đầy đủ các nhu cầu phẫu thuật từ đơn giản đến phức tạp. Chúng tôi cung cấp đa dạng các loại đại phẫu, tiểu phẫu bao gồm:"], ["h4", "1. Phẫu thuật đỡ đẻ , mổ đẻ cho chó mèo"], ["p", "Nhiều người khi nghe đến từ mổ hay phẫu thuật sẽ nghĩ răng đây là việc nguy hiểm. Tuy nhiên, giống như ở người, việc mổ đẻ cho chó mèo sẽ giúp tăng khả năng an toàn cho mẹ và con non gần như tuyệt đối. Như đã nói, việc mổ đẻ cho chó mèo sẽ giúp con non không bị chết trong hoặc sau khi sinh do ngạt thở hoặc nhiễm trùng. Giúp con mẹ nhanh thoát khỏi cơn đau đẻ, tránh mất máu và kiệt sức đến chết khi rặn đẻ."], ["h4", "2. Phẫu thuật sa trực tràng"], ["img", "/mock-images/dv/phau-thuat-5.jpg"], ["p", "Phẫu thuật sa thực tràng là cắt bỏ phần thực tràng thoát ra khỏi hậu môn, gây đau đớn cho vật nuôi, khiến chúng lâu lớn, gầy guộc. Phẫu thuật sa trực tràng sẽ loại bỏ phần đó, đảm bảo sức khỏe ổn định cho vật nuôi."], ["p", "Nguyên nhân gây sa trực tràng bao gồm: táo bón mãn tính, chó mèo rặn đẻ nhiều và lâu; Ảnh hưởng từ thuốc khi dùng thuốc liều cao; Ảnh hưởng từ bệnh viêm ruột già, viêm trực tràng; Cơ nâng hậu môn yếu; Cơ thể thiếu nước dẫn đến tăng quá trình co bóp…"], ["h4", "3. Phẫu thuật nối ruột, tháo ruột"], ["p", "Phẫu thuật này được thực hiện do vật nuôi bị tổn thương ở ruột như cắn nhau bị lòi ruột, ruột bị xoắn, ruột bị tổn thương cần nối lại… Các bác sĩ sẽ tiến hành mổ bụng chó mèo, tìm lại đoạn ruột bị thương hoặc bị rách để nối lại, sắp xếp lại các đoạn ruột bị xoắn."], ["h4", "4. Phẫu thuật cắt mống mắt"], ["p", "Chó bị mộng mắt cũng vì khó chịu mà gãi mắt, dẫn tới bệnh càng thêm nặng thành viêm kết mạc. Viêm giác mạc, mờ giác mạc hoặc loét, ảnh hưởng đến thị lực. Nghiêm trọng có thể dẫn tới mù lòa."], ["p", "Nếu có vấn đề với mắt mà không điều trị kịp thời sẽ ảnh hưởng tới sinh hoạt của chó trong tương lai. Mặc dù chó bị mộng mắt không phải bệnh quá nguy hiểm nhưng nếu không điều trị kịp thời sẽ khiến cơ thể và cả tâm trí thú cưng sẽ rất buồn và mệt mỏi. Bạn nên quan sát và mang thú cưng đến Vet Clinic để cắt mống mắt đó."], ["h4", "5. Phẫu thuật triệt sản"], ["p", "Về độ an toàn và tốt cho chó thì nên triệt sản bằng phương pháp phẫu thuật.Với phương pháp triệt sản này thì người nuôi chỉ cần mang chó tới các bệnh viện thú y . Tại đây các bác sỹ sẽ gây mê và phẫu thuật triệt sản cho chó theo đúng kỹ thuật và theo dõi chăm sóc chó sau khi phẫu thuật để chó hồi phục tốt nhất."], ["p", "Chắc hẳn không ít người băn khoăn về việc triệt sản chó cái bằng phẫu thuật sẽ khiến cho bị đau, nhiễm trùng. Nhưng các bạn đừng lo lắng, việc phẫu thuật triệt sản cho chó cái sẽ rất nhanh, và chó sẽ mau bình phục và ăn uống bình thường."], ["h4", "6. Phẫu thuật mổ Hernie"], ["p", "Hernie là hiện tượng chó bị sa ruột (thoát vị rốn). Có một số chó mèo bị dị tật bẩm sinh tại rốn có một lỗ hổng không được đóng kín. Từ đó các nội tạng trong bụng theo lỗ này thoát ra ngoài tạo nên chứng hernie. Ban đầu, ở rốn xuất hiện cục thịt nhỏ bằng ngón tay nhô lên. Theo thời gian cục u này to dần gây nguy hiểm cho chó mèo. Hernie dù được phẫu thuật thành công nhưng dễ tái lại."], ["h4", "7. Phẫu thuật mổ sạn bàng quang, mổ sỏi thận"], ["img", "/mock-images/dv/phau-thuat-6.jpg"], ["p", "Giống như chúng ta, bệnh sỏi bàng quang cũng có thể xảy ra với những chú cún cưng trong gia đình bạn. Sỏi bàng quang nếu không được giải quyết sớm sẽ gây tắc nghẽn – đặc biệt là ở chó mèo đực, những con có niệu đạo hẹp hơn – có thể ngăn không cho cho mèo của bạn đi tiểu. Một số dấu hiệu của tắc nghẽn đường tiết niệu là nôn mửa, buồn nôn, chán ăn và bụng cứng. Chính vì vậy, việc can thiệp bằng phẫu thuật để lấy sỏi ra hỏi cơ thế là phương pháp hiệu quả nhất."], ["h4", "8. Phẫu thuật tháo khớp"], ["img", "/mock-images/dv/phau-thuat-7.jpg"], ["p", "Phẫu thuật tháo khớp để loại bỏ phần chân bị hoại tử do vết thương bên ngoài. Nếu không tháo khớp phần bị hoại tử sẽ khiến chỗ hoại tử đó ăn dần ra và làm hỏng những bộ phận còn lại."], ["h4", "9. Phẫu thuật mổ xuyên đinh"], ["p", "Phẫu thuật mổ xuyên đinh áp dụng khi chó mèo bị tai nạn gãy xương chân. Nếu chỉ bị gãy và xương còn dính với nhau thì chỉ đơn giản là bó bột nẹp cố định xương, Nhưng nếu bị nặng xương gãy lìa hẳn, thì lúc này bác sĩ thú y phải dùng cây đinh dài xuyên qua giữa 2 lớp xương bị gãy để giữ nối xương lại."], ["h4", "10. Tiểu phẫu khâu da"], ["p", "Đối với những vết thương nghiêm trọng và không thể tự lành, bạn cần đưa chó đi khám thú y ngay. Những vết thương đâm sâu qua da và ảnh hưởng đến cơ, gân và lớp mỡ bên trong cần được xử lý chuyên nghiệp. Sau khi đánh giá, bác sĩ thú y có thể khâu vết thương cho chó để giúp vết thương mau lành."], ["h4", "11. Tiểu phẫu cắt đuôi"], ["p", "Cắt đuôi chó là việc nên làm với một số giống chó. Điều này có lợi cho sự trưởng thành của chúng. Nếu cắt đuôi từ nhỏ thì vết thương sẽ rất mau lành và ít đau. Nhưng với chó lớn thì cần sự can thiệp của thuốc mê và hậu phẫu."], ["h4", "12. Tiểu phẫu khối máu tụ vành tai"], ["p", "Tụ máu vành tai là hiện tượng máu tụ trong vành tai cả máu tươi và đông. Khi đó vành tai sẽ dày lên, xốp và sưng một phần hoặc toàn phần. Nguyên nhân là do chúng lắc, gãi tai quá mực hoặc vết thương do cắn."], ["p", "Tụ máu vành tai nên được điều trị sớm trước khi để lại biến dạng vĩnh viễn cho tau. Điều trị bằng tiểu phẫu gồm những bước:"], ["p", "Rạch một đường nhỏ trên vành tai để dẫn lưu máu, loại bỏ các cục máu đồng; sau đó các bác sĩ sẽ may ép để loại bỏ không gian trống, gắn kết sụn với da ngăn ngừa tái phát trong tương lai."], ["p", "Khi cần chăm sóc thú cưng của bạn đừng quên tới Bệnh Viện Thú YVet Clinic."]]}, "tiem-phong": {"title": "Dịch vụ chích ngừa cho chó mèo", "blocks": [["p", "Chích ngừa cho chó mèo là việc làm hết sức quan trọng và cần thiết mà các chủ thú cưng phải làm. Chích ngừa giúp chó mèo của bạn tránh được những bệnh nguy hiểm, đảm bảo an toàn cho cả thú cưng, chủ nuôi và những người xung quanh. Chính vì vậy Vet Clinic cung cấp dịch vụ chích ngừa uy tín tại Cần Thơ."], ["h2", "Dịch vụ chích ngừa chó mèo của Vet Clinic"], ["p", "Chích ngừa cho chó mèo là biện pháp y tế dự phòng vô cùng cần thiết cho vật nuôi ngay từ khi chúng còn nhỏ cho tới khi trưởng thành. Việc chích ngừa cho chó mèo không chỉ giúp phòng tránh cách bệnh nguy hiểm và còn tăng sức đề kháng, đảm bảo sức khỏe cho chúng."], ["h3", "1. Chích ngừa cho chó"], ["img", "/mock-images/dv/tiem-phong-1.jpg"], ["p", "Chích ngừa cho chó là phương pháp gây miễn dịch chủ động để phòng ngừa bệnh tật ở chúng. Kháng thể được tạo ra sau khi tiêm vắc-xin giúp thú cưng chống lại các bệnh nguy hiểm, bệnh không có thuốc chữa, bệnh truyền nhiễm, từ đó bảo vệ sức khỏe và tính mạng của thú cưng."], ["p", "Việc chích ngừa cho chó đúng thời điểm và quy trình sẽ ngăn ngừa được các dịch bệnh thường gặp trên chó như:"], ["li", "Bệnh dại Rabies"], ["li", "Bệnh Care, là bệnh do virus gây xuất huyết đường tiêu hóa, tiêu chảy ra máu, nôn mửa, ho khạc kéo dài, động kinh."], ["li", "Bệnh do Pavovirus, gây nôn mửa, mất nước nhanh, tiể ra máu hôi thanh, chó dễ chết."], ["li", "Bệnh viêm gan truyền nhiễm (nôn mửa, tiêu ra máu, đau bụng, co giật)"], ["li", "Bệnh Lepto, gây nôn mửa, tiêu chảy ra máu, vàng da, có thể lây sang người."], ["li", "Bệnh viêm khí quản, phế quản truyền nhiễm (viêm mũi, viêm phổi, ho khan kéo dài, suy kiệt cơ thể…)"], ["p", "Đối với việc phòng các bệnh truyền nhiễm, chó con khoảng 7-8 tuần tuổi nên được tiêm lần đầu, tiêm lại sau khoảng 3-4 tuần. Các lần tiêm phòng tiếp theo là theo lịch định kỳ hàng năm. Tẩy giun trước khi tiêm phòng 5-7 ngày sẽ giúp hiệu quả hơn. Tùy vào độ tuổi, thể trạng, giống chó mà bác sĩ thú y sẽ khuyên bạn nên tiêm chủng vắc-xin như thế nào cho hợp lí."], ["li", "Chó 6 tuần tuổi: Tiêm vắc-xin tổng hợp 5 bệnh (Bệnh Carre virus, Bệnh do Parvo virus, Bệnh viêm gan truyền nhiễm, Bệnh ho cũi chó, Bệnh phó cúm)"], ["li", "Chó 9 tuần tuổi: Tiêm mũi 2 vắc-xin tổng hợp 7 bệnh (Bệnh Carre virus, Bệnh do Parvo virus, Bệnh viêm gan truyền nhiễm, Bệnh ho cũi chó, Bệnh phó cúm, Bệnh do Leptospira, Bệnh Coronavirus)"], ["li", "Chó 12 tuần tuổi: Tiêm mũi 3 vắc-xin tổng hợp 7 bệnh (Bệnh Carre virus, Bệnh do Parvo virus, Bệnh viêm gan truyền nhiễm, Bệnh ho cũi chó, Bệnh phó cúm, Bệnh do Leptospira, Bệnh Coronavirus)"], ["li", "Chó 15 tuần tuổi: Tiêm 1 mũi vắc-xin phòng bệnh dại. (Dành cho giống chó nhỏ) Chó đã chích ngừa đầy đủ cũng cần tiêm nhắc lại định kỳ hàng năm 1 mũi vắc-xin tổng hợp 7 bệnh và 1 mũi vắc-xin phòng dại. ​Việc phòng tránh các căn bệnh nguy hiểm này vẫn luôn được đảm bảo hiệu quả khi thực hiện chích ngừa chó mèo tại nhà."], ["h3", "2. Chích ngừa cho mèo"], ["img", "/mock-images/dv/tiem-phong-2.jpg"], ["p", "Cũng như chích ngừa cho chó thì tích ngừa cho cho mèo cũng rất cần thiết để bảo vệ sức khỏe cho mèo trước sự tấn công của nhiều nguồn gây bệnh. Mèo con được tiêm phòng lần đầu ở tuần tuổi thứ 8, sau đó 3-4 tuần thì tiêm lại lần nữa. Để việc tiêm phòng đạt hiệu quả, bạn nên tẩy giun cho mèo trước 5-7 ngày."], ["p", "Chích ngừa cho mèo có thể chống lại được những các bệnh truyền nhiễm nguy hiểm như:"], ["li", "Bệnh Calicivirus (C): gây sổ mũi (như bệnh cảm cúm)"], ["li", "Bệnh Rhinotracheitic/Herpes Virus (H): Virus Herpes gây cúm ở mèo với biểu hiện chính là chảy nước mũi."], ["li", "Bệnh Panleukopenia Virus (P): Gọi là bệnh sốt ban ở mèo, gây viêm dạ dày, ruột nghiêm trọng, có thể dẫn đến tử vong."], ["p", "Chích ngừa dại cho mèo là điều bắt buộc do tỉ lệ mèo ở nước ta có nguy cơ dại rất cao, giúp ngừa bệnh dại cũng như bảo đảm an toàn cho chủ nuôi. Lịch tiêm chích ngừa cho mèo cũng tuân theo một lịch trình cụ thể tùy theo độ tuổi của chúng."], ["li", "Mèo từ 7 tuần tuổi: Tiêm vắc-xin tổng hợp 4 bệnh (Bệnh Giảm bạch cầu, Bệnh Viêm mũi – khí quản truyền nhiễm, Bệnh Hô hấp do Herpevirus)"], ["li", "Mèo từ 10 tuần tuổi: Tiêm vắc-xin tổng hợp 4 bệnh (Bệnh Giảm bạch cầu, Bệnh Viêm mũi – khí quản truyền nhiễm, Bệnh Hô hấp do Herpevirus)"], ["li", "Mèo từ 13 tuần tuổi: Tiêm vắc-xin tổng hợp 4 bệnh (Bệnh Giảm bạch cầu, Bệnh Viêm mũi – khí quản truyền nhiễm, Bệnh Hô hấp do Herpevirus) và tiêm vắc-xin phòng bệnh dại."], ["p", "Mèo được tiêm phòng đầy đủ nên tiêm lại vắc-xin tổng hợp 4 bệnh và vắc-xin phòng dại hàng năm. Chích ngừa cho mèo là cần thiết và gần như bắt buộc để thú cưng của bạn luôn được khỏe mạnh. Việc chích ngừa chó mèo tại nhà vẫn luôn đảm bảo hiệu quả phòng tránh bệnh như bình thường."], ["h2", "Những điều cần biết khi chích chó mèo"], ["img", "/mock-images/dv/tiem-phong-3.jpg"], ["p", "Chích ngừa bằng vắc-xin nào sẽ do bác sĩ thú y quyết định dựa vào các tiêu chí như lứa tuổi, giống chó mèo, tình trạng sức khỏe, nguy cơ lây bệnh từ vật nuôi mang bệnh khác, tình hình dịch bệnh tại khu vực đó…"], ["p", "Để việc chích ngừa chó mèo đạt hiệu quả tốt, chúng ta cần lưu ý các điều sau:"], ["li", "Không chích ngừa cho chó mèo trong khoảng 10 ngày đầu khi mới mua về. Lúc này, sức khỏe chó mèo chưa tốt, khả năng tạo miễn dịch thấp."], ["li", "Cần kiểm tra sức khỏe của chó mèo trước khi tiêm phòng, không tiêm khi thú cưng có biểu hiện lạ, sức khỏe không tốt."], ["li", "Tìm hiểu chế độ ăn uống, dinh dưỡng cho chó mèo sau khi tiêm phòng như tránh các thức ăn có nhiều dầu mỡ, sữa, đồ tanh."], ["li", "Không tắm cho cho thú cưng sau khi tiêm chủng, kiêng tắm ít nhất 1 tuần."], ["li", "Tẩy giun cho thú cưng trước khi tiêm phòng từ 5-7 ngày để đạt hiệu quả tốt nhất."], ["li", "Duy trì chích ngừa đầy đủ và tiêm nhắc lại định kỳ mỗi năm theo lời khuyên của bác sĩ thú y."], ["p", "Chích ngừa sai không những không có tác dụng mà còn có thể làm thú cưng mắc bệnh, gây ảnh hưởng xấu tới sức khỏe của thú cưng. Vì vậy không nên tự ý chích ngừa tại nhà khi chưa có sự hướng dẫn chi tiết của các bác sĩ. Hơn hết, nếu bạn không có đủ thời gian thì việc lựa chọn dịch vụ chích ngừa chó mèo tại nhà để đảm bảo hiệu quả và an toàn cho thú cưng."], ["h2", "Lưu ý khi tiêm chủng cho chó mèo"], ["img", "/mock-images/dv/tiem-phong-4.jpg"], ["p", "Trước khi tiêm cho chó mèo cần :"], ["li", "Vệ sinh thân thể sạch sẽ cho trẻ nhằm hạn chế tình trạng nhiễm trùng."], ["li", "Cho chó con ăn thật đầy đủ chất dinh dưỡng một ngày trước khi tiêm vắc-xin. Việc này giúp tăng hệ thống miễn dịch của chú chó, giúp việc tiêm phòng hiệu quả hơn."], ["li", "Trao đổi rõ với bác sĩ về tình trạng sức khỏe của thú cưng: tiền sử mắc bệnh, suy dinh dưỡng (nếu có) để xem xét và quyết định có nên tiêm chủng hay không."], ["li", "Mang theo sổ hoặc phiếu tiêm chủng để bác sĩ tham vấn và đảm bảo thực hiện đúng lịch tiêm vacxin cho chó mèo."], ["li", "Ghi chú về các loại thuốc thú cưng đang sử dụng, các loại vacxin hoặc thức ăn mà chó mèo của bạn đã từng bị dị ứng trước đó."], ["p", "Một số trường hợp chống chỉ định tiêm phòng cho chó mèo :"], ["li", "Chó, mèo có tiền sử sốc hoặc phản ứng nặng sau tiêm chủng."], ["li", "Chó, mèo có tình trạng suy chức năng các cơ quan hô hấp, tuần hoàn, suy tim, suy thận, suy gan…"], ["li", "Chó, mèo đang mang thai và chó con mới sinh"], ["li", "Chó mẹ, mèo mẹ sau khi sinh nửa tháng"], ["li", "Chó mẹ, mèo con đang bị bệnh"], ["p", "Cách chăm sóc và theo dõi chó con sau tiêm chủng:"], ["p", "Tại phòng khám:"], ["li", "Sau tiêm chủng, cho chó ở lại theo dõi 30 phút tại khu vực chờ để phát hiện sớm các phản ứng sau tiêm có thể xảy ra."], ["p", "Khi về nhà:"], ["li", "Sau khi tiêm xong cần chăm sóc chó tốt hơn, kiêng tắm; Kiêng thức ăn có chứa nhiều mỡ, sữa, đồ tanh ít nhất là 1 tuần."], ["li", "Tiến hành tẩy giun sau khi tiêm phòng 1 tuần."], ["li", "Không dùng các loại thuốc kháng sinh, kháng viêm trong vòng 14 ngày sau khi chích"], ["li", "Không cho tiếp xúc với thú cưng bị bệnh vì vẫn có khả năng lây bệnh."], ["li", "Liên lạc với bệnh viện thú y nếu thấy thú cưng có dấu hiệu bất thường xử lí kịp thời…"], ["h2", "Dịch vụ chích ngừa chó mèo tại nhà của Vet Clinic"], ["img", "/mock-images/dv/tiem-phong-5.jpg"], ["p", "Dịch vụ điều trị tiêm chủng chó mèo tại nhà tức là các chủ nuôi không phải mang chó mèo đến cơ sở phòng khám thú y mà đội ngũ bác sĩ thú y sẽ tới tận nơi tư vấn và tiêm phòng cho thú cưng của bạn. Dịch vụ này rất tiện lợi, được nhiều khách hàng tin dùng, vừa tiết kiệm được thời gian, công sức cho chủ nuôi, vừa giúp thăm khám, tiêm chủng điều trị bệnh cho chó mèo được nhanh chóng, hiệu quả, an toàn."], ["p", "Tại sao bạn nên chọn Vet Clinic để chích ngừa chó mèo tại nhà?"], ["li", "Đội ngũ nhân viên đông đảo, có kinh nghiệm, sẵn sàng hỗ trợ mọi khách hàng 24/24 trong trường hợp khẩn cấp."], ["li", "Thú cưng được cấp chuồng điều trị nếu phải theo dõi và chăm sóc trong một thời gian dài."], ["li", "Nguồn thuốc và vắc-xin là hàng chất lượng, có nguồn gốc xuất xứ rõ ràng."], ["li", "Thiết bị hỗ trợ đầy đủ, đồng bộ, máy móc hiện đại được nhập khẩu từ nước ngoài…"], ["li", "Thú cưng được kiểm tra sức khỏe và tư vấn trước khi tiêm phòng."], ["li", "Các bác sĩ thú y giỏi chuyên môn, yêu thương động vật, có trách nhiệm cao trong công việc."], ["p", "Khi cần chăm sóc thú cưng của bạn đừng quên tới Bệnh Viện Thú YVet Clinic."]]}, "rang-mieng": {"title": "Dịch vụ chăm sóc răng miệng toàn diện cho chó mèo", "blocks": [["p", "Chăm sóc răng miệng cho chó mèo là việc hết sức quan trọng nhưng dễ bị bỏ qua trong quá trình chăm sóc thú cưng. Việc không quan tâm đến sức khỏe răng miệng cho thú cưng sẽ dẫn đến nhiều hệ lụy, ảnh hưởng trực tiếp đến sức khỏe thú cưng, và đến các bộ phận bên trong cơ thể nghiêm trọng."], ["p", "Chính vì thế, Thú yVet Clinic cung cấp cho bạn dịch vụ chăm sóc răng miệng chó mèo giúp chúng tránh khỏi những bệnh tật nguy hiểm liên quan đến răng miệng của chúng."], ["img", "/mock-images/dv/rang-mieng-1.jpg"], ["h3", "Khi nào cần đưa chó mèo đi khám răng miệng?"], ["p", "Việc không thường xuyên vệ sinh răng miệng có thể gây một loạt vấn đề về răng miệng cụ thể như:"], ["li", "Lợi chảy máu"], ["li", "Hơi thở hôi"], ["li", "Đau miệng"], ["li", "Cao răng vàng hoặc nâu trên răng"], ["li", "Mất răng hoặc răng lung lay"], ["li", "Chảy nước miếng bất thường"], ["li", "Gặp khó khăn khi ăn uống"], ["p", "Nếu bạn nhận thấy thú cưng của mình có một trong những vấn đề trên, bạn nên đưa thú cưng đến gặp bác sĩ thú y để được tư vấn, thăm khám."], ["h3", "Dịch vụ chăm sóc răng miệng cho chó mèo là như thế nào?"], ["p", "Dịch vụ chăm sóc răng miệng là quá trình thăm khám tổng quát miệng, đánh giá tình trạng răng của thú cưng. Từ đó, đưa ra các biện pháp xử lý phù hợp, nhằm cải thiện tình trạng sức khỏe răng miệng cho thú cưng."], ["p", "Việc vệ sinh răng miệng toàn diện chỉ có thể được thực hiện khi con vật cưng được gây mê toàn thân. Gây mê sẽ giúp con vật cưng của bạn không bị đau trong quá trình làm răng và cho phép bác sĩ thú y của bạn kiểm tra đầy đủ hàm răng và loại bỏ răng có dấu hiệu yếu và bị bệnh."], ["h3", "Tại sao nên sử dụng dịch vụ chăm sóc chó mèo chuyên nghiệp?"], ["img", "/mock-images/dv/rang-mieng-2.jpg"], ["p", "Bảo vệ và chăm sóc răng miệng cho thú cưng sẽ giúp chúng khỏe mạnh hơn. Sử dụng những dịch vụ chăm sóc răng miệng cho chó mèo giúp chúng không chỉ có một bộ răng đẹp, trắng, sạch sẽ mà giúp cho việc ăn uống của chúng được thoải mái, hệ tiêu hóa ổn định, hấp thu tốt, chóng lớn."], ["p", "Khám nha khoa và lấy cao răng định kỳ 2 lần/năm là công việc cần thiết nếu bạn muốn chăm thú cưng một cách khoa học"], ["h3", "Quy trình chăm sóc răng miệng cho chó mèo tạiVet Clinic"], ["p", "Bước 1: Tiếp nhận thú cưng"], ["p", "Bước 2: Kiểm tra toàn bộ khoang miệng nhằm phát hiện, đánh giá tình trạng mức độ tổn thương. Kiểm tra môi, lưỡi, và toàn bộ miệng nếu có vết thương, hoặc các vấn đề khác"], ["p", "Bước 3: Loại bỏ các mảng bám và cao răng miệng nhìn thấy bám vào bên ngoài răng"], ["p", "Bước 4: Loại bỏ mảng bám và cao răng bên mặt trong của răng"], ["p", "Bước 6: Đánh bóng răng tránh trầy xước men răng có thể thu hút vi khuẩn"], ["p", "Bước 7: Xóa bỏ hoặc sửa chữa răng nứt hoặc bị nhiễm vi khuẩn"], ["p", "Bước 8: Hoàn thiện kiểm tra lại răng miệng cho chó mèo."], ["h3", "5 lý do bạn nên sử dụng dịch vụ chăm sóc răng miệng cho chó mèo tạiVet Clinic"], ["img", "/mock-images/dv/rang-mieng-3.jpg"], ["li", "Là một trong những phòng khám thú y uy tín tại Sài Gòn."], ["li", "Vet Clinic đã có hơn 10 năm kinh nghiệm trong lĩnh vực thú y."], ["li", "Trang thiết bị tại Vet Clinic rất hiện đại, đạt tiêu chuẩn của Bộ y tế."], ["li", "Vet Clinic cung cấp rất nhiều dịch vụ phục vụ đủ nhu cầu của thú cưng."], ["li", "100% bác sĩ thú y tạiVet Clinic được đào tạo chuyên sâu trong nước và nước ngoài."], ["p", "Với những lý do này, chắc chắn bạn sẽ yên tâm và cảm thấy hài lòng khi đưa thú cưng đến với Vet Clinic."], ["p", "Mọi thắc mắc xin vui lòng liên hệ trung tâmVet Clinic để được tư vấn và giải đáp kịp thời nhất nhé!"], ["p", "Khi cần chăm sóc thú cưng của bạn đừng quên tới Bệnh Viện Thú YVet Clinic."]]}, "spa-grooming": {"title": "Làm đẹp cho thú cưng với dịch vụ spa & grooming", "blocks": [["p", "Những thú cưng đáng yêu từ lâu nay đã trở thành người bạn đồng hành thân thiết của con người. Muốn người bạn nhỏ nay luôn khỏe mạnh , xinh đẹp thì người chủ phải bỏ công chăm sóc từ thức ăn đến tắm rửa, cắt tỉa lông thường xuyên."], ["p", "Thế nhưng, không phải sen nào cũng có nhiều thời gian để tìm hiểu cách làm và thực hiện việc vệ sinh, chăm sóc thú cưng của mình đúng cách. Vì vậy, spa grooming – dịch vụ chăm sóc thú cưng toàn diện củaVet Clinic chính là một sự lựa chọn thông minh cho bạn."], ["h3", "Tìm hiểu về spa grooming là gì?"], ["img", "/mock-images/dv/spa-grooming-1.jpg"], ["p", "Nghe có vẻ lạ, nhưng spa grooming là một thuật ngữ khá phổ biến của cộng đồng chăm sóc thú cưng. Hiện tại, nó được hiểu là dịch vụ bao gồm cắt tỉa lông, tắm gội,… nhằm giúp thú cưng của bạn được thư giãn, thoải mái, phát triển một cách toàn diện nhất. Tất cả được làm một cách chuyên nghiệp bởi đội ngũ nhân viên được đào tạo bài bản."], ["h3", "Có nên sử dụng dịch vụ spa cho chó mèo không?"], ["p", "Đối với những người yêu động vật , đặc biệt là chó mèo , chủ nuôi luôn mong muốn chăm sóc bạn đồng hành thật khỏe mạnh. Nhưng việc nuôi thú cưng thật sự không đơn giản. Bởi lẽ ,rất khó có thể hiểu được thú cưng của bạn muốn gì. Vì vậy , việc sử dụng dịch spa cho thú cưng là NÊN LÀM."], ["p", "Dịch vụ spa giúp tiết kiệm thời gian cho bạn rất nhiều, bạn chỉ việc bấm máy và đặt lịch sẽ có ngay nhân viên tới đón bé yêu của bạn đi làm đẹp."], ["p", "Khi sử dụng các dịch vụ spa, những chú chó mèo ngoan hơn, bởi chúng sẽ được xả stress và căng thẳng, đồng thời giúp loại bỏ những bụi bẩn, mùi khó chịu trên da, lông, thậm chí sâu trong khe kẽ mà mắt thường không nhìn thấy được"], ["p", "Việc vệ sinh tại nhà giúp bạn tiết kiệm chi phí nhưng lại không dễ dàng, nhất là nếu bạn chỉ có một mình và không có dụng cụ hỗ trợ chuyên dụng."], ["p", "Sử dụng dịch vụ spa còn giúp bạn biết được vấn đề sức khỏe của thú cưng bởi các chuyên gia luôn am hiểu rất rõ về các giống chó mèo."], ["h3", "Cùng tham khảo dịch vụ ởVet Clinic"], ["img", "/mock-images/dv/spa-grooming-2.jpg"], ["p", "Khi đến petVet Clinic tút tát lại cho thú cưng bạn sẽ được chuyên viên ở đây tư vấn và làm theo quy trình như sau:"], ["li", "Bước 1: kiểm tra thể trạng sức khỏe, lông, da và chân… Các vấn đề sẽ được ghi đầy đủ trên giấy đón thú cưng"], ["li", "Bước 2: Dựa vào bước kiểm tra ban đầu các chuyên viên sẽ tư vấn các kiểu cắt lông, vệ sinh phù hợp đối với tình trạng cún cho khách lựa chọn."], ["li", "Bước 3: Vệ sinh – nhổ lông tai, khử mùi hôi cho thú cưng."], ["li", "Bước 4: Cắt – dũa móng"], ["li", "Bước 5: Cạo vệ sinh bàn chân, lông bụng, hậu môn."], ["li", "Bước 6: Gỡ lông rối"], ["li", "Bước 7: Tắm gội vệ sinh bằng nước ấm"], ["li", "Bước 8: Vắt tuyến hôi giúp làm giảm mùi cơ thể cho thú cưng ."], ["li", "Bước 9: Spa và massage trong lúc tắm giúp thú cưng được thư giãn."], ["li", "Bước 10: Sấy đánh tơi giúp cho các bé trông như những cục bông thật đáng yêu."], ["li", "Bước 11: Cắt và tạo kiểu theo yêu cầu hoặc tạo kiểu phù hợp với các bé"], ["li", "Bước 12: Xịt dưỡng lông, giúp lông thơm mát, mềm mại."], ["h3", "Một vài lưu ý khi đưa thú cưng đi spa tạiVet Clinic"], ["img", "/mock-images/dv/spa-grooming-3.jpg"], ["p", "Để có một buổi spa thú cưng lành mạnh và các thú cưng hợp tác với nhân viên, chủ nuôi cần thực hiện một số vấn đề sau:"], ["li", "Đưa thú cưng đi tiêm phòng đầy đủ khi được 3 tháng tuổi."], ["li", "Đảm bảo chú chó có sức khỏe tốt, thực hiện đầy đủ các biện pháp phòng ngừa kí sinh trùng đầy đủ."], ["li", "Đối với những bé chó mèo có dấu hiệu bệnh truyền nhiễm, viêm da, ký sinh trùng năng, hệ thống Spa thú cưng củaVet Clinic sẽ thông báo và hướng dẫn chủ nuôi chuyển bé qua Vet Clinic để chữa bệnh."], ["li", "Dây xích, vòng cổ, lồng vận chuyển, túi, ba lô chuyên dụng, quần áo nếu có. Rọ mõm, vòng chống liếm tránh trường hợp cắn và liếm."], ["li", "Lưu lại lịch tiêm chủng để có thể cung cấp các thông tin cần thiết cho bác sỹ."], ["p", "Không chỉ tự hào là hệ thống bán lẻ các sản phẩm dành cho thú cưng cao cấp trong suốt hơn 5 năm qua, màVet Clinic vinh dự là thương hiệu có dịch vụ spa chăm sóc thú cưng chuyên nghiệp và chất lượng nhất."], ["p", "Vet Clinic với cơ sở vật chất hiện đại, đội ngũ nhân viên tay nghề cao hứa hẹn sẽ cung cấp đầy đủ mọi loại hình dịch vụ chăm sóc và làm đẹp trọn gói tốt nhất dành cho người bạn đồng hành của quý khách hàng. Được chăm sóc định kỳ và thường xuyên sẽ đem lại nhiều lợi ích cho sức khỏe thú cưng, vì vậy còn chần chừ gì nữa, hãy đến ngayVet Clinic thôi!"], ["p", "Khi cần chăm sóc thú cưng của bạn đừng quên tới Bệnh Viện Thú YVet Clinic."]]}};
